def rambling_sentence_length(prompts, completions, answer, **kwargs):
    import re

    scores = []
    for completion in completions:
        text = completion[0]['content']
        # Split into sentences
        sentences = re.split(r'(?<=[.!?])\s+', text)

        long_sentences = 0
        total_sentences = len(sentences)

        for s in sentences:
            if len(s.split()) > 30:  # More than 30 words
                long_sentences += 1

        if total_sentences == 0:
            scores.append(0.0)
            continue

        ratio = long_sentences / total_sentences

        if ratio > 0.5:
            scores.append(-1.5)
        elif ratio > 0.3:
            scores.append(-0.8)
        elif ratio > 0.1:
            scores.append(-0.3)
        else:
            scores.append(0.5)
    return scores

def repetition_density_penalty(prompts, completions, answer, **kwargs):
    scores = []
    for completion in completions:
        text = completion[0]['content']
        words = text.lower().split()
        if len(words) < 10:
            scores.append(0.0)
            continue

        # Calculate 4-gram repetition
        n = 4
        grams = []
        for i in range(len(words) - n + 1):
            gram = tuple(words[i:i+n])
            grams.append(gram)

        if not grams:
            scores.append(0.0)
            continue

        unique_grams = len(set(grams))
        total_grams = len(grams)
        repetition_ratio = 1.0 - (unique_grams / total_grams)

        # Penalize high repetition
        if repetition_ratio > 0.5:
            scores.append(-2.0)
        elif repetition_ratio > 0.3:
            scores.append(-1.0)
        elif repetition_ratio > 0.15:
            scores.append(-0.5)
        else:
            scores.append(0.0)
    return scores

